   {"code": "OUTCOME_DERIVED_LABEL", "text": "Play types and counter labels are derived from play-by-play points, which are themselves the outcome variable, so adherence can be tautologically linked to winning."}
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": ["FAM:SF-APPS-003", "FAM:SF-APPS-018", "FAM:SF37", "FAM:SF-APPS-068"],
  "summary": "No retrieved record tests series-level adherence to a suppression-conditional mix against wins. The related records test engine hit rates, playsheet ranking, possession-level PPP and team-season PCI. Three of the four were flagged as artifacts or inconclusive for leakage, fidelity or small-sample reasons, and none offers a usable positive estimate for the stated question."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "54 series is too few for a binary outcome unless the effect is very large; a null result would be uninformative."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "Adherence must be computed from information available before each series. Recorded leakage problems in earlier families make this a high risk."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Play types and counter labels derived from points can encode the outcome."},
  {"code": "MEASURE_RELIABILITY", "text": "Low fidelity (16.5%) between proxy and production engine means the adherence variable may be mismeasured."},
  {"code": "CONFOUNDING", "text": "Team strength, seed, injuries, home court and series-specific matchups could drive both adherence and winning."},
  {"code": "BASE_RATE", "text": "Series favorites win at high base rates; a naive adherence-win association can reflect favorites that adhere more."},
  {"code": "EXPOSURE_SPARSITY", "text": "Some play types have very few instances (for example POST_UP 0/4 in SF-APPS-003), so series-level adherence may be sparse for certain mixes."},
  {"code": "MULTIPLE_TESTING", "text": "Multiple engine variants, thresholds and calibrations have been tried in this project; selection among them inflates false positives."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Play-style and rule changes across 2022-23 to 2025-26 may change the adherence-win relation over time."},
  {"code": "LABEL_ERROR", "text": "Play-type classification from the NBA stats API may be inconsistent across seasons, adding misclassification to the adherence variable."},
  {"code": "PLACEBO_DEPENDENCE", "text": "Without a placebo or negative-control mix, the apparent adherence effect cannot be separated from general team quality."}
 ],
 "predicted_outcome": {
  "supported": 0.07,
  "rejected": 0.18,
  "untestable": 0.10,
  "artifact": 0.20,
  "uncertain": 0.45
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Among playoff series, the difference in win probability for the team with higher pre-series adherence to the suppression-conditional mix, conditional on pre-series team strength, seed and home-court advantage. Minimum viable test only; not for the question as posed.",
  "unit": "Series-team dyad (two rows per series), with series as the clustering unit.",
  "sample": "Playoff series from 2022-23 to 2024-25 only (complete). Exclude 2025-26 playoffs until complete (from 2026-06-21). Report the exact series count after exclusions and reconcile it with the 54 recorded units.",
  "power": "State up front that power is low: about 0.35–0.40 detectable difference in win probability at 80% power with 54 series (own calculation). Pre-register a minimum effect of interest or report the test as exploratory.",
  "controls": "Pre-series team strength (for example a prior-season net rating or Elo), seed, home-court, injury/availability flags, and series-level matchup features. Adherence computed only from games before each series, with time-stamped labels. Play-type labels frozen before outcome linkage. Validate fidelity against the production engine on a held-out sample before analysis, with a minimum fidelity threshold (for example 70%).",
  "falsification": "Pre-register a negative-control mix (non-suppression-conditional or randomly permuted recommendations) and a placebo time window. The adherence effect should disappear for the placebo. Also test whether the adherence coefficient shrinks when controlling for team strength.",
  "multiplicity": "One pre-registered primary test (adherence coefficient, cluster-robust by series). Other engine variants reported as exploratory with correction (for example Holm), or none.",
  "decision_rule": "Claim support only if the primary adherence coefficient has a 95% cluster-robust CI excluding zero, survives the strength and seed controls, and the placebo mix shows no effect. Report 'uncertain' if the CI spans zero and the study is underpowered; do not report a null as evidence of no effect.",
  "data_version": "NBA stats API per-game files, 2022-23 to 2024-25 regular and playoff seasons, frozen at a dated snapshot before analysis. 2025-26 playoff data excluded until complete (from 2026-06-21); 2025-26 regular season used only for pre-series strength if complete (from 2026-04-13)."
 }
}

